INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Kiwira Coal Mine (Songwe-Kiwira coalfield)', 'State Mining Corporation of Tanzania (STAMICO) — via Kiwira Coal & Power Company Ltd', 'Special Mining License SML-233/2005 (Ivogo Ridge); Prospecting License PL-9963/2014 (Kabulo Ridge)', NULL, NULL, 'Tanzania', 'Songwe Region', 'Kiwira area, Ivogo Ridge, Ileje District, Songwe Region, Tanzania', -9.40, 33.85, 'Dar es Salaam (road/rail ~800km); coastal access limited', 'TAZARA railway (Tanzania-Zambia Railway) — passes through Mbeya; 100km from mine', 1988, 37, 'Government of Tanzania (STAMICO)', '[{"year": 1988, "event": "STAMICO developed Kiwira Coal Mine with Chinese assistance — operations commenced"}, {"year": 2005, "event": "Privatised — TanPower Resources Ltd acquired 85% of Kiwira Coal Production Company (KCPC); government retained 15%"}, {"year": 2012, "event": "TANESCO signed US$271.8m contract with KCPC for 400 MW of coal-fired electricity — but deal never executed"}, {"year": 2013, "event": "Operations ceased; all workers laid off"}, {"year": 2019, "event": "President Magufuli directed transfer of all TanPower shares back to government; STAMICO resumed control"}, {"year": 2022, "event": "Mining operations restarted by STAMICO; infrastructure rehabilitation 98% complete as of February 2022"}]'::jsonb, '[{"year": null, "event": "Only STAMICO-operated coal mine in Tanzania (the other — Ngaka — is operated by the Tancoal JV)"}, {"year": 2011, "event": "2011 production: 96,000 tonnes per annum (installed capacity 150,000 tonnes/year)"}, {"year": null, "event": "85 million tonnes coal resources at Ivogo and Kabulo Ridges (latest feasibility study)"}, {"year": null, "event": "Proposed 200 MW coal-fired power plant (Kiwira Coal to Power Project) — included in TANESCO August 2023 priority projects list"}, {"year": null, "event": "Target production post-2022 restart: 50,000 tonnes/month (600,000 tonnes/year)"}, {"year": 2024, "event": "July 2024: 200 MW plant still on TANESCO priority project list"}, {"year": null, "event": "Products: Run of Mine (ROM) and processed coal; CV 5,000–6,200 kcal/kg"}]'::jsonb, '[]'::jsonb, NULL, 'Sub-bituminous', 'CV 5,000–6,200 kcal/kg; Karoo Supergroup; Ivogo Ridge and Kabulo Ridge coal deposits', 5600, NULL, NULL, NULL, NULL, 600000, NULL, 'Underground drift/adit mining', NULL, NULL, NULL, NULL, NULL, 'Dar es Salaam', '["Road", "TAZARA railway (100km to Mbeya)"]'::jsonb, NULL, false, '[]'::jsonb)
ON CONFLICT (mine_name, country) DO UPDATE SET operator = EXCLUDED.operator, license_number = EXCLUDED.license_number, contact_email = EXCLUDED.contact_email, contact_phone = EXCLUDED.contact_phone, region = EXCLUDED.region, address = EXCLUDED.address, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, nearest_port = EXCLUDED.nearest_port, nearest_railway = EXCLUDED.nearest_railway, founded_year = EXCLUDED.founded_year, years_in_operation = EXCLUDED.years_in_operation, original_owner = EXCLUDED.original_owner, ownership_changes = EXCLUDED.ownership_changes, major_milestones = EXCLUDED.major_milestones, notable_incidents = EXCLUDED.notable_incidents, estimated_mine_life_remaining_years = EXCLUDED.estimated_mine_life_remaining_years, coal_type = EXCLUDED.coal_type, grade = EXCLUDED.grade, calorific_value_kcal_kg = EXCLUDED.calorific_value_kcal_kg, moisture_percent = EXCLUDED.moisture_percent, ash_percent = EXCLUDED.ash_percent, sulfur_percent = EXCLUDED.sulfur_percent, size_mm = EXCLUDED.size_mm, annual_capacity_tonnes = EXCLUDED.annual_capacity_tonnes, available_stock_tonnes = EXCLUDED.available_stock_tonnes, mining_method = EXCLUDED.mining_method, price_per_tonne_usd = EXCLUDED.price_per_tonne_usd, price_basis = EXCLUDED.price_basis, minimum_order_tonnes = EXCLUDED.minimum_order_tonnes, payment_terms = EXCLUDED.payment_terms, contract_types = EXCLUDED.contract_types, loading_port = EXCLUDED.loading_port, transport_modes = EXCLUDED.transport_modes, lead_time_days = EXCLUDED.lead_time_days, export_license = EXCLUDED.export_license, certifications = EXCLUDED.certifications, updated_at = NOW();

INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Ngaka Coal Mine (Ngaka coalfield / Ruvuma Region)', 'Tancoal Energy Limited — JV: Intra Energy Tanzania Limited (IETL) 70% and National Development Corporation (NDC) 30%', 'Large-scale mining licence — Ngaka area, Mbinga District, Ruvuma Region', NULL, NULL, 'Tanzania', 'Ruvuma Region', 'Ngaka area, Mbinga District, Ruvuma Region, Tanzania', -10.73, 34.93, 'Mtwara (road; ~400km southeast) or Dar es Salaam (1,100km)', 'No direct rail connection — road transport only', 2011, 14, 'Intra Energy Corporation (IEC) / NDC', '[{"year": 2011, "event": "Tancoal Energy Limited established as 50/50 JV (later 70/30); commenced mining operations August 2011 at Mbalawala sub-basin (South Ngaka)"}, {"year": 2012, "event": "MoU with TANESCO signed for 120–200 MW coal power plant development"}, {"year": 2015, "event": "MoU with Sinohydro signed for 200 MW power plant (not advanced)"}, {"year": 2020, "event": "IEC/Tancoal confirms government has not approved coal-fired power station for southern Tanzania; focus remains on coal sales to cement industry"}]'::jsonb, '[{"year": null, "event": "Largest operational coal mine in Tanzania and East Africa"}, {"year": null, "event": "NDC reports 423 million tonnes coal reserve; Tancoal reports 367 Mt proven resources in Ngaka Basin"}, {"year": 2019, "event": "FY2019 production: 748,874 tonnes; FY2019 sales: 788,702 tonnes"}, {"year": 2020, "event": "FY2020 production: 496,852 tonnes; sales 523,027 tonnes (−34% — COVID impact and artisanal miner competition)"}, {"year": null, "event": "Current selling capacity: ~600,000 tonnes per annum (unwashed coal)"}, {"year": null, "event": "Main customers: cement factories in Tanga, Mbeya, Dar es Salaam, Mtwara; regional exports to Malawi, Kenya, Uganda, Zambia, Rwanda"}, {"year": null, "event": "Proposed 200 MW Ngaka power plant (planned mine-mouth; 7km from mine) — not approved as of 2025"}]'::jsonb, '[{"year": null, "event": "Community health impacts reported in Ruanda Ward (neighbouring community) — dust, water quality concerns documented in local reporting"}]'::jsonb, NULL, 'Bituminous thermal', 'Mbalawala sub-basin (212 Mt proven) and Mbuyura-Mkapa sub-basin (200 Mt proven); total basin potential up to 1 billion tonnes', NULL, NULL, NULL, NULL, NULL, 600000, NULL, 'Open cast — truck-and-shovel; ROM coal sold unwashed and processed', NULL, NULL, NULL, NULL, NULL, 'Mtwara or Dar es Salaam', '["Road transport to domestic customers and regional ports"]'::jsonb, NULL, true, '[]'::jsonb)
ON CONFLICT (mine_name, country) DO UPDATE SET operator = EXCLUDED.operator, license_number = EXCLUDED.license_number, contact_email = EXCLUDED.contact_email, contact_phone = EXCLUDED.contact_phone, region = EXCLUDED.region, address = EXCLUDED.address, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, nearest_port = EXCLUDED.nearest_port, nearest_railway = EXCLUDED.nearest_railway, founded_year = EXCLUDED.founded_year, years_in_operation = EXCLUDED.years_in_operation, original_owner = EXCLUDED.original_owner, ownership_changes = EXCLUDED.ownership_changes, major_milestones = EXCLUDED.major_milestones, notable_incidents = EXCLUDED.notable_incidents, estimated_mine_life_remaining_years = EXCLUDED.estimated_mine_life_remaining_years, coal_type = EXCLUDED.coal_type, grade = EXCLUDED.grade, calorific_value_kcal_kg = EXCLUDED.calorific_value_kcal_kg, moisture_percent = EXCLUDED.moisture_percent, ash_percent = EXCLUDED.ash_percent, sulfur_percent = EXCLUDED.sulfur_percent, size_mm = EXCLUDED.size_mm, annual_capacity_tonnes = EXCLUDED.annual_capacity_tonnes, available_stock_tonnes = EXCLUDED.available_stock_tonnes, mining_method = EXCLUDED.mining_method, price_per_tonne_usd = EXCLUDED.price_per_tonne_usd, price_basis = EXCLUDED.price_basis, minimum_order_tonnes = EXCLUDED.minimum_order_tonnes, payment_terms = EXCLUDED.payment_terms, contract_types = EXCLUDED.contract_types, loading_port = EXCLUDED.loading_port, transport_modes = EXCLUDED.transport_modes, lead_time_days = EXCLUDED.lead_time_days, export_license = EXCLUDED.export_license, certifications = EXCLUDED.certifications, updated_at = NOW();

INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Mchuchuma/Katewaka Coal Deposit (Ruhuhu Basin / Njombe Region)', 'Tanzania China International Mineral Resources Ltd (TCIMRL) — JV: Sichuan Hongda Group (China) 80%, NDC (Tanzania) 20%', 'Special Mining Licenses (SML) for Mchuchuma Coal and Liganga Iron Ore (held by TCIMRL)', NULL, NULL, 'Tanzania', 'Njombe Region', 'Mchuchuma area, Ludewa District, Njombe Region, Tanzania', -10.40, 34.67, 'Mtwara (road via Songea, ~500km); Dar es Salaam (rail if SGR line built)', 'No current rail connection; Mtwara-Liganga-Mchuchuma SGR proposed as part of Mtwara Development Corridor', 2011, NULL, 'Sichuan Hongda Group / NDC', '[{"year": 2011, "event": "JV contract signed between Government of Tanzania (via NDC 20%) and Sichuan Hongda Group/TCIMRL (80%) — US$3 billion integrated project: coal mine (3 Mtpa) + 600 MW power station + iron ore/steel plant"}, {"year": 2012, "event": "Drilling exploration completed; 428 Mt coal reserve established"}, {"year": 2021, "event": "ESIA certificates and mining/water licenses obtained; Strategic Investor Status Certificate signed"}, {"year": 2024, "event": "New feasibility study commenced (July 2024); TCIMRL still holds valid SMLs"}, {"year": 2025, "event": "Feasibility update ongoing; TCIMRL awaiting tax incentive gazettement before proceeding"}]'::jsonb, '[{"year": null, "event": "Largest planned coal-power project in Tanzania history — $3 billion integrated coal, iron and power complex"}, {"year": null, "event": "428 million tonnes coal reserve (Mchuchuma); 400 million tonnes iron ore reserve (Liganga)"}, {"year": null, "event": "Planned: 3 million tonnes/year coal mine + 600 MW power station (4×150 MW)"}, {"year": null, "event": "Identified as national flagship project in Tanzania Five-Year Plan 2021/22–2025/26"}, {"year": 2024, "event": "May 2024: President Samia directs expedite; new updated feasibility study commissioned"}]'::jsonb, '[]'::jsonb, NULL, 'Bituminous thermal', 'Ruhuhu Basin Karoo sediments; seams suitable for open cut and underground; associated with Liganga iron ore deposit', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Open cast (planned capacity 3 Mtpa)', NULL, NULL, NULL, NULL, NULL, 'Mtwara (proposed SGR)', '["Proposed SGR railway (Mtwara Development Corridor); road during development"]'::jsonb, NULL, false, '[]'::jsonb)
