INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Maamba Coal Mine (Maamba coalfield / Gwembe Valley)', 'Maamba Energy Limited (MEL) — formerly Maamba Collieries Limited (MCL)', 'Mining title held since 1970; encompasses ~7,900 hectares in Siankondobo coalfield, Gwembe Valley', NULL, NULL, 'Zambia', 'Southern Province', 'Maamba town, Sinazongwe District, Southern Province, Zambia', -17.37, 27.14, 'No direct port — landlocked; coal consumed domestically', 'No direct railway to mine — road transport; 48km 330kV transmission line to national grid', 1967, 58, 'Government of Zambia', '[{"year": 1967, "event": "Maamba Collieries Limited (MCL) established; coal production commenced — Zambia''s first domestic coal mine, prompted by Rhodesian UDI cutting Hwange coal supply"}, {"year": 1971, "event": "MCL incorporated as formal company under Government of Zambia ownership"}, {"year": 2010, "event": "MCL privatised through JV: Nava Bharat (Singapore) acquired 65%, ZCCM Investment Holdings retained 35%. Investment: US$919 million total (mine revival + 300 MW power plant)"}, {"year": 2016, "event": "300 MW mine-mouth thermal power station commissioned (7 August 2016) by President Edgar Lungu — first coal-fired power station in Zambia"}, {"year": 2024, "event": "Company renamed Maamba Energy Limited (MEL); ZCCM-IH committed US$15m towards 300 MW Phase II expansion (to 600 MW total)"}]'::jsonb, '[{"year": null, "event": "Zambia''s only commercial coal mine and largest Independent Power Producer (IPP)"}, {"year": null, "event": "300 MW mine-mouth thermal power plant — first in Zambia; ~8–9% of Zambia''s installed generation capacity (2023)"}, {"year": null, "event": "Reserves: 103 Mt high-grade + 70 Mt low-grade = 173 Mt"}, {"year": 2024, "event": "Phase II expansion: additional 300 MW plant (600 MW total); construction commenced August 2024; target commissioning August 2026"}, {"year": null, "event": "48km 330kV double-circuit transmission line from mine to national grid"}]'::jsonb, '[{"year": null, "event": "Spontaneous combustion and acid mine drainage documented from pre-2010 low-grade coal stockpiles in Maamba town — Nava Bharat/MEL project included environmental remediation of legacy waste heaps"}]'::jsonb, NULL, 'Bituminous thermal', 'Lower Karoo Gwembe Formation; fault-controlled basins in Mid-Zambezi Rift Valley; seams 1–5m thick', NULL, NULL, NULL, NULL, NULL, 175000, NULL, 'Open cast; coal handling and processing plant on site', NULL, NULL, NULL, NULL, NULL, 'None — all coal for mine-mouth power generation', '["Short conveyor / road to adjacent 300 MW power plant"]'::jsonb, NULL, false, '[]'::jsonb)
ON CONFLICT (mine_name, country) DO UPDATE SET operator = EXCLUDED.operator, license_number = EXCLUDED.license_number, contact_email = EXCLUDED.contact_email, contact_phone = EXCLUDED.contact_phone, region = EXCLUDED.region, address = EXCLUDED.address, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, nearest_port = EXCLUDED.nearest_port, nearest_railway = EXCLUDED.nearest_railway, founded_year = EXCLUDED.founded_year, years_in_operation = EXCLUDED.years_in_operation, original_owner = EXCLUDED.original_owner, ownership_changes = EXCLUDED.ownership_changes, major_milestones = EXCLUDED.major_milestones, notable_incidents = EXCLUDED.notable_incidents, estimated_mine_life_remaining_years = EXCLUDED.estimated_mine_life_remaining_years, coal_type = EXCLUDED.coal_type, grade = EXCLUDED.grade, calorific_value_kcal_kg = EXCLUDED.calorific_value_kcal_kg, moisture_percent = EXCLUDED.moisture_percent, ash_percent = EXCLUDED.ash_percent, sulfur_percent = EXCLUDED.sulfur_percent, size_mm = EXCLUDED.size_mm, annual_capacity_tonnes = EXCLUDED.annual_capacity_tonnes, available_stock_tonnes = EXCLUDED.available_stock_tonnes, mining_method = EXCLUDED.mining_method, price_per_tonne_usd = EXCLUDED.price_per_tonne_usd, price_basis = EXCLUDED.price_basis, minimum_order_tonnes = EXCLUDED.minimum_order_tonnes, payment_terms = EXCLUDED.payment_terms, contract_types = EXCLUDED.contract_types, loading_port = EXCLUDED.loading_port, transport_modes = EXCLUDED.transport_modes, lead_time_days = EXCLUDED.lead_time_days, export_license = EXCLUDED.export_license, certifications = EXCLUDED.certifications, updated_at = NOW();

-- ─────────────────────────── ZIMBABWE ───────────────────────────

INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Chaba Coal Mine — Hwange Colliery Company (Hwange coalfield)', 'Hwange Colliery Company Limited (HCCL) — under Administration/Reconstruction (since 2022); now HCCL Holdings', 'Multiple mining grants covering Hwange coalfield; Matabeleland North', NULL, NULL, 'Zimbabwe', 'Matabeleland North Province', 'Hwange town, Matabeleland North, Zimbabwe', -18.38, 26.47, 'Beira, Mozambique (~1,200km by rail via Harare-Mutare) or Durban, South Africa (via rail)', 'HCCL owns its own railway system; handover to National Railways of Zimbabwe (NRZ) at Thomson Junction', 1899, 126, 'British South Africa Company', '[{"year": 1899, "event": "Wankie Colliery Company established — mining operations commenced"}, {"year": 1903, "event": "Wankie (Private) Limited incorporated; shares sold to Rhodesian Anglo American Ltd"}, {"year": 1972, "event": "Wankie disaster — 426 miners killed (deadliest mine accident in Zimbabwe history)"}, {"year": 1982, "event": "Renamed Hwange Colliery Company Limited following renaming of Wankie to Hwange"}, {"year": 2006, "event": "Chaba Mine (opencast) commenced operations February 2006"}, {"year": 2018, "event": "ZSE listing suspended November 2018 due to financial distress"}, {"year": 2022, "event": "Placed under Administration due to financial and operational challenges"}, {"year": 2023, "event": "Zimbabwe government approved reconstruction plan; HCCL Holdings formed"}]'::jsonb, '[{"year": null, "event": "Zimbabwe''s oldest coal mine (founded 1899) — 125+ years of continuous operation"}, {"year": null, "event": "Produces both thermal coal (for power stations) and metallurgical/coking coal (export)"}, {"year": 2022, "event": "1,198,539 tonnes delivered to Hwange Power Station in 2022 (63% increase year-on-year)"}, {"year": null, "event": "Hwange Power Station (1,520 MW) is primary customer"}, {"year": null, "event": "Coking coal exported to regional markets (South Africa, Mozambique)"}]'::jsonb, '[{"year": 1972, "event": "Wankie Colliery Disaster — 6 June 1972: 426 miners killed in underground explosion — deadliest mine accident in Zimbabwe history"}, {"year": 2018, "event": "ZSE listing suspended November 2018 due to financial distress"}]'::jsonb, NULL, 'Bituminous — thermal and coking/metallurgical', 'Vitrinite-rich bright banded coking coal (main seam) and durain-rich power/thermal coal; Karoo Supergroup', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Open cast dragline (Chaba Mine) + underground bord-and-pillar', NULL, NULL, NULL, NULL, NULL, 'Beira or Durban', '["HCCL-owned railway to Thomson Junction", "NRZ national rail network", "Road"]'::jsonb, NULL, true, '[]'::jsonb)
