VALUES ('Entuba Colliery / Makomo Resources (Hwange coalfield)', 'Makomo Resources (Pvt) Ltd — under corporate rescue since ~2021; contractor South Mining engaged from March 2023', 'Special Grant — Entuba Coalfields, Hwange District, Matabeleland North', NULL, NULL, 'Zimbabwe', 'Matabeleland North Province', 'Entuba area, southeast of Hwange town, Matabeleland North, Zimbabwe', -18.50, 26.60, 'Beira or Durban (via NRZ rail)', 'Entuba Siding enables rail transport to Munyati, Bulawayo and Harare Power Stations; NRZ', 2010, 15, 'Makomo Resources (Pvt) Ltd', '[{"year": 2010, "event": "Makomo Resources established; Entuba Coal Mine commenced operations"}, {"year": 2016, "event": "Makomo becomes Zimbabwe largest coal miner by output; ZPC contract for 60,000 tonnes/month"}, {"year": 2021, "event": "Placed under corporate receivership/rescue due to financial and operational challenges"}, {"year": 2023, "event": "Resumed operations August 2023 after engaging South Mining as contractor; signed new ZPC contract for Units 7 & 8 supply"}, {"year": 2024, "event": "Planning underground mining project to selectively mine coking coal"}]'::jsonb, '[{"year": null, "event": "At peak (2016–2020): Zimbabwe largest coal miner by output — surpassed HCCL"}, {"year": 2021, "event": "2021 production: 1.72 million metric tonnes ROM (largest surface and underground mine in Zimbabwe per GlobalData)"}, {"year": 2024, "event": "2024 projected production: 3.6 million tonnes (prioritising coking coal over thermal coal)"}, {"year": null, "event": "7,000 hectare concession; LOM 18 years open cast + 30 years underground = 48 years total at 3 Mtpa"}, {"year": null, "event": "Plant capacity: 300,000 tonnes/month (3.6 Mtpa)"}, {"year": null, "event": "Products: Thermal coal, Washed Peas, Washed Nuts, Washed Duff, Washed Fines"}]'::jsonb, '[{"year": null, "event": "Environmental controversy: Proximity to Hwange National Park; coal mining disrupting biodiversity, wildlife"}]'::jsonb, NULL, 'Bituminous — thermal and coking', 'Karoo Supergroup; 7,000 hectare concession', NULL, NULL, NULL, NULL, NULL, 1720000, NULL, 'Open cast (primary); planning underground mine (coking coal)', NULL, NULL, NULL, NULL, NULL, 'Beira or Durban', '["Road (own truck fleet)", "Rail (Entuba Siding — NRZ; 6 Makomo locomotives)"]'::jsonb, NULL, true, '[]'::jsonb)
