VALUES ('Sengwa Coal Mine / Sengwa Colliery (Sengwa coalfield)', 'Sengwa Colliery / Rio Energy Limited (subsidiary of RioZim Limited) — no commercial mining has begun', 'Coal mining license granted 1989 to Sengwa Colliery (RioZim and Rio Tinto); subsequent licenses under RioZim/Rio Energy', NULL, NULL, 'Zimbabwe', 'Midlands Province', 'Sengwa area, Gokwe North District, Midlands Province, Zimbabwe', -18.10, 28.15, 'Beira or Durban (via planned rail)', 'No current rail; 250km water pipeline from Lake Kariba proposed', NULL, NULL, 'RioZim Limited / Rio Tinto', '[{"year": 1989, "event": "Zimbabwe government granted coal mining license to Sengwa Colliery — jointly owned by Rio Zimbabwe Limited (RioZim) and Rio Tinto"}, {"year": 1997, "event": "Gokwe North Power Station project first proposed — not implemented due to economic conditions"}, {"year": 2020, "event": "Industrial and Commercial Bank of China (ICBC) signed formal expression of interest for Sengwa 2.8 GW plant — awarded to RioZim"}, {"year": 2021, "event": "ICBC withdrew — stated bad plan due to environmental problems; RioZim sought alternative financing"}, {"year": 2024, "event": "RioZim still seeking financing partners; Sengwa in funding stage; RioZim seeking $2.1 billion for 1,400 MW plant + mine"}]'::jsonb, '[{"year": null, "event": "538 million tonnes estimated coal reserves"}, {"year": null, "event": "Proposed 2,800 MW coal-fired power plant (4 phases x 700 MW each) — one of Africa''s most ambitious proposed coal projects"}, {"year": null, "event": "Identified as one of world''s 425 carbon bombs (fossil fuel projects with 1+ Gt CO2 potential)"}, {"year": 2021, "event": "ICBC withdrew from financing in June 2021 — first case of a Chinese bank proactively abandoning a coal project on environmental grounds"}, {"year": null, "event": "No mining has commenced despite 35+ years of proposed development"}]'::jsonb, '[]'::jsonb, NULL, 'Bituminous — coking and thermal', 'Karoo Supergroup; Vitrinite-rich bright banded coking coal and durain-rich power coal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Open cast (planned)', NULL, NULL, NULL, NULL, NULL, 'Beira or Durban (planned)', '["Road / rail (planned); 250km water pipeline from Lake Kariba proposed"]'::jsonb, NULL, false, '[]'::jsonb)
