VALUES ('Entuba Colliery — Chilota Collieries / JINGAN Corporation (Hwange coalfield)', 'JINGAN Corporation — Chinese-Zimbabwean JV; Chilota Collieries as operating entity', 'Special Grant — Hwange area, Matabeleland North (separate from HCCL/Makomo grants)', NULL, NULL, 'Zimbabwe', 'Matabeleland North Province', 'Hwange area, Matabeleland North, Zimbabwe', -18.40, 26.50, 'Beira or Durban (via NRZ)', 'NRZ rail network', 2020, 5, 'JINGAN Corporation (Chinese-Zimbabwean JV)', '[{"year": 2020, "event": "Chilota Collieries (JINGAN Corp JV) commenced operations — invested ~US$12 million; started producing coking coal (May 2020)"}, {"year": 2020, "event": "Also deployed equipment to Chaba Mine (HCCL) under contract mining arrangement for thermal coal production for ZPC"}]'::jsonb, '[{"year": 2020, "event": "Producing 30,000 tonnes coking coal/month at own Chilota site; 30,000 tonnes thermal coal/month at Chaba Mine under HCCL contract"}, {"year": null, "event": "Part of Government of Zimbabwe''s programme of contracting Chinese miners on state land concessions under Hwange Colliery"}, {"year": null, "event": "ZPC power-expansion programme driving demand for coal contractors"}]'::jsonb, '[{"year": null, "event": "Environmental and community concerns: Chinese mining operations in Hwange District documented as destructive in nature affecting biodiversity and livelihoods"}, {"year": null, "event": "Dinde, Deka, Lusumbami communities affected by environmental destruction, water and air pollution"}]'::jsonb, NULL, 'Bituminous — coking (primary) and thermal', 'Hwange Coalfield; coking coal primary product', NULL, NULL, NULL, NULL, NULL, 720000, NULL, 'Open cast truck-and-shovel', NULL, NULL, NULL, NULL, NULL, 'Beira or Durban', '["Road", "Rail (NRZ)"]'::jsonb, NULL, true, '[]'::jsonb)
